import time, requests

def get_bling(url, token, params=None, tentativas=5):
    for i in range(tentativas):
        r = requests.get(url, params=params, timeout=60,
                         headers={"Authorization": f"Bearer {token}", "enable-jwt": "1"})
        if r.status_code != 429:
            r.raise_for_status()
            return r.json()
        periodo = r.json().get("error", {}).get("period")
        if periodo == "day":
            raise RuntimeError("Cota diária (120 mil) esgotada: retome amanhã")
        time.sleep(2 ** i)  # 1, 2, 4, 8 s
    raise RuntimeError("429 persistente")

