// Com o kit Bling: o script agendado "python cliente.py renovar --excel <planilha>" grava o token
// na tabela tbConfig; a consulta Parametros le essa tabela e fnApi usa Parametros[AccessToken].
// Aqui so ha leitura: nenhuma chamada a /oauth/token acontece dentro do Power Query.
let
    Dados = fnApi("contas/receber", [
        #"situacoes[]" = {"1"},
        tipoFiltroData = "V",
        dataInicial = Parametros[DataInicial],
        dataFinal = Parametros[DataFinal]
    ], true),
    Tabela = Table.FromRecords(Dados, {"id", "vencimento", "valor", "situacao"}, MissingField.UseNull),
    Tipos = Table.TransformColumns(Tabela, {
        {"id", each try Int64.From(_) otherwise null, Int64.Type},
        {"vencimento", each try Date.FromText(_) otherwise null, type date},
        {"valor", each try Number.From(_) otherwise null, type number}
    })
in
    Tipos
